# Generates original illustrated placeholder images -> images/*.jpg. Replace any with real photos of the same name.
def sh(x,b,w): return f'<ellipse cx="{x+w/2}" cy="{b+4}" rx="{w*.62}" ry="9" fill="#000" opacity=".13"/>'
def hl(x,b,w,h): return f'<rect x="{x+w*.1}" y="{b-h*.92}" width="{w*.07}" height="{h*.8}" rx="4" fill="#fff" opacity=".22"/>'
def jar(x,b,w,h,body,lid,lab): return sh(x,b,w)+f'<rect x="{x}" y="{b-h}" width="{w}" height="{h}" rx="{w*.16}" fill="{body}"/><rect x="{x+w*.06}" y="{b-h-w*.17}" width="{w*.88}" height="{w*.2}" rx="6" fill="{lid}"/><rect x="{x+w*.12}" y="{b-h*.72}" width="{w*.76}" height="{h*.42}" rx="8" fill="{lab}"/><circle cx="{x+w/2}" cy="{b-h*.51}" r="{w*.1}" fill="{body}" opacity=".8"/>'+hl(x,b,w,h)
def bottle(x,b,w,h,body,cap,lab):
    nw=w*.4;bh=h*.62
    return sh(x,b,w)+f'<rect x="{x+(w-nw)/2}" y="{b-h}" width="{nw}" height="{h*.5}" rx="6" fill="{body}"/><rect x="{x+(w-nw)/2-3}" y="{b-h-w*.16}" width="{nw+6}" height="{w*.2}" rx="5" fill="{cap}"/><rect x="{x}" y="{b-bh}" width="{w}" height="{bh}" rx="{w*.3}" fill="{body}"/><rect x="{x+w*.1}" y="{b-bh*.82}" width="{w*.8}" height="{bh*.5}" rx="8" fill="{lab}"/>'+hl(x,b,w,bh)
def can(x,b,w,h,body,band): return sh(x,b,w)+f'<rect x="{x}" y="{b-h}" width="{w}" height="{h}" rx="12" fill="{body}"/><rect x="{x}" y="{b-h*.62}" width="{w}" height="{h*.26}" fill="{band}"/><ellipse cx="{x+w/2}" cy="{b-h+4}" rx="{w/2-4}" ry="9" fill="#fff" opacity=".35"/>'+hl(x,b,w,h)
def bag(x,b,w,h,body,lab): return sh(x,b,w)+f'<rect x="{x}" y="{b-h}" width="{w}" height="{h}" rx="14" fill="{body}"/><rect x="{x}" y="{b-h}" width="{w}" height="{h*.09}" rx="8" fill="#000" opacity=".14"/><circle cx="{x+w/2}" cy="{b-h*.5}" r="{w*.26}" fill="{lab}"/><rect x="{x+w*.3}" y="{b-h*.2}" width="{w*.4}" height="9" rx="4" fill="{lab}" opacity=".8"/>'
def box(x,b,w,h,body,lab): return sh(x,b,w)+f'<rect x="{x}" y="{b-h}" width="{w}" height="{h}" rx="6" fill="{body}"/><rect x="{x}" y="{b-h*.7}" width="{w}" height="{h*.34}" fill="{lab}"/><rect x="{x+w*.12}" y="{b-h*.9}" width="{w*.5}" height="9" rx="4" fill="{lab}"/>'
def bar(x,b,w,h,body): return sh(x,b,w)+f'<rect x="{x}" y="{b-h}" width="{w}" height="{h}" rx="8" fill="{body}"/>'+"".join(f'<rect x="{x+w*.5-2}" y="{b-h}" width="4" height="{h}" fill="#000" opacity=".15"/>')+"".join(f'<rect x="{x}" y="{b-h*k/4-2}" width="{w}" height="4" fill="#000" opacity=".15"/>' for k in (1,2,3))
def sack(x,b,w,h,body,lab): return sh(x,b,w)+f'<path d="M{x+w*.2} {b-h} H{x+w*.8} L{x+w} {b-h*.8} V{b} H{x} V{b-h*.8} Z" fill="{body}" stroke="{body}" stroke-width="14" stroke-linejoin="round"/><rect x="{x+w*.14}" y="{b-h*.98}" width="{w*.72}" height="11" rx="5" fill="#000" opacity=".15"/><rect x="{x+w*.15}" y="{b-h*.62}" width="{w*.7}" height="{h*.34}" rx="10" fill="{lab}"/>'
def cookie(x,y,r): return f'<circle cx="{x}" cy="{y}" r="{r}" fill="#C58B4F"/>'+"".join(f'<circle cx="{x+dx*r}" cy="{y+dy*r}" r="{r*.12}" fill="#5A3622"/>' for dx,dy in((-.4,-.3),(.3,-.4),(.1,.3),(-.3,.4),(.5,.2)))
def scene(bg,items,W=1200,H=800,base=330): return f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}"><rect width="{W}" height="{H}" fill="{bg}"/><circle cx="{W/2}" cy="{base-110}" r="330" fill="#fff" opacity=".45"/><rect y="{base}" width="{W}" height="{H-base}" fill="#000" opacity=".07"/><g transform="translate(600 330) scale(.85) translate(-600 -430)">{items}</g></svg>'
C="#FFF8EA"
def product_svg(kind,body,acc):
    f={"jar":lambda:jar(70,200,100,125,body,acc,C),"bottle":lambda:bottle(80,200,80,170,body,acc,C),"can":lambda:can(75,200,90,140,body,C),"bag":lambda:bag(65,200,110,150,body,C),"box":lambda:box(70,200,100,150,body,acc),"sack":lambda:sack(60,200,120,150,body,acc),"bar":lambda:bar(80,200,80,120,body)}[kind]()
    return f'<svg viewBox="0 0 240 240" role="img" aria-label="Product illustration">{f}</svg>'
